const accessory = (p: LookPiece, image: Asset, panel: AccessoryResult['panel']): AccessoryResult => ({ piece: p, image, panel });

const finishingSteps = (upTo: number): RenderStep[] => {
	const all: [string, number, number][] = [
		['Face analysis', 30, 9],
		['Gold sandals', 2, 31],
		['Makeup', 1, 14],
		['Hairstyle', 2, 27],
		['Earrings', 1, 12],
		['Necklace', 1, 11],
		['Watch', 1, 13],
		['Ring', 1, 12]
	];
	return all.map(([label, units, seconds], i) =>
		i < upTo
			? { label, status: 'done', units, seconds }
			: i === upTo
				? { label, status: 'rendering', units }
				: { label, status: 'pending', units }
	);
};

